int vhost_dev_addr_to_iov(struct vhost_dev *dev, u64 addr, u32 len,
                          struct iovec iov[], int iov_size) {
    int count = 0;
    struct vhost_memory *mem = &dev->mem;
    struct vhost_memory_region *reg;
    int i;

    if (!mem->regions)
        return -EFAULT;

    vhost_dev_lock_read(dev);

    for (i = 0; i < mem->nregions; i++) {
        reg = &mem->regions[i];

        if (addr >= reg->guest_addr &&
            addr + len <= reg->guest_addr + reg->size) {
            iov[count].iov_base = (void *)(uintptr_t)(addr + reg->userspace_addr -
                                                       reg->guest_addr);
            iov[count].iov_len = len;
            count++;
            break;
        } else if (addr >= reg->guest_addr &&
                   addr + len > reg->guest_addr + reg->size) {
            iov[count].iov_base = (void *)(uintptr_t)(addr + reg->userspace_addr -
                                                       reg->guest_addr);
            iov[count].iov_len = reg->guest_addr + reg->size - addr;
            count++;

            if (count >= iov_size)
                break;

            len -= iov[count - 1].iov_len;
            addr += iov[count - 1].iov_len;
            i--;
        } else {
            continue;
        }
    }

    vhost_dev_unlock_read(dev);

    if (i < mem->nregions)
        return -EFAULT;

    if (addr != addr + len)
        return -EFAULT;

    return count;
}

int vhost_get_iov(struct vhost_dev *dev, u64 addr, u32 len,
                  struct iovec iov[], int iov_size)
{
    int nr_iov = 0;
    void *vaddr;
    size_t vlen;

    if (!dev || !iov || iov_size <= 0)
        return -EINVAL;

    vhost_dev_lock_read(dev);

    while (len > 0) {
        if (nr_iov >= iov_size) {
            vhost_dev_unlock_read(dev);
            return -ENOBUFS;
        }

        if (vhost_dev_translate(dev, addr, &vaddr, &vlen)) {
            vhost_dev_unlock_read(dev);
            return -EFAULT;
        }

        iov[nr_iov].iov_base = vaddr;
        iov[nr_iov].iov_len = min(len, vlen);

        addr += iov[nr_iov].iov_len;
        len -= iov[nr_iov].iov_len;
        nr_iov++;
    }

    vhost_dev_unlock_read(dev);
    return nr_iov;
}

int vhost_get_vhost_dev_iov(struct vhost_dev *dev, u64 addr, u32 len,
                            struct iovec iov[], int iov_size)
{
    int n = 0;
    struct vhost_memory *mem = &dev->memory;
    int i;

    if (!dev || !mem || !iov || iov_size <= 0)
        return -EINVAL;

    vhost_dev_lock_read(dev);

    for (i = 0; i < mem->nreg && addr < addr + len; i++) {
        struct vhost_mem_region *reg = &mem->regions[i];
        u64 reg_start = reg->guest_phys_addr;
        u64 reg_end = reg->guest_phys_addr + reg->size;
        u64 start = max(addr, reg_start);
        u64 end = min(addr + len, reg_end);
        u64 offset = start - reg_start;

        if (start >= end)
            continue;

        iov[n].iov_base = reg->userspace_addr + offset;
        iov[n].iov_len = end - start;

        if (++n >= iov_size) {
            vhost_dev_unlock_read(dev);
            return -EFAULT;
        }
    }

    vhost_dev_unlock_read(dev);

    if (n == 0)
        return -EFAULT;

    return n;
}

int vhost_dev_translate_address(struct vhost_dev *dev, u64 addr, u32 len,
                                struct iovec iov[], int iov_size)
{
    int count = 0;
    u64 offset = 0;

    if (!dev || !iov || iov_size <= 0)
        return -EINVAL;

    vhost_dev_lock_read(dev);

    while (offset < len) {
        struct vhost_memory *mem = dev->memory;
        struct vhost_mem_region *region;
        u64 region_start, region_end;

        if (!mem || !mem->regions || mem->nregions == 0) {
            vhost_dev_unlock_read(dev);
            return -EFAULT;
        }

        region = NULL;
        for (size_t i = 0; i < mem->nregions; i++) {
            region_start = (u64)(uintptr_t)mem->regions[i].guest_phys_addr;
            region_end = region_start + mem->regions[i].size;

            if (addr + offset >= region_start && addr + offset < region_end) {
                region = &mem->regions[i];
                break;
            }
        }

        if (!region) {
            vhost_dev_unlock_read(dev);
            return -EFAULT;
        }

        u64 start = addr + offset;
        u64 end = start + (region_end - start);
        u64 vec_len = end - start;

        if (count >= iov_size) {
            vhost_dev_unlock_read(dev);
            return -ENOMEM;
        }

        iov[count].iov_base = (void *)((uintptr_t)region->userspace_addr +
                                       (start - region->guest_phys_addr));
        iov[count].iov_len = vec_len;
        count++;
        offset += vec_len;
    }

    vhost_dev_unlock_read(dev);
    return count;
}

int vhost_dev_get iov (struct vhost_dev *dev, u64 addr, u32 len,
                       struct iovec iov[], int iov_size)
{
    int ret = 0;
    int i = 0;

    if (!dev || !iov || iov_size <= 0)
        return -EINVAL;

    vhost_dev_lock_read(dev);

    while (len > 0 && i < iov_size) {
        struct vhost_memory *mem = dev->mem;
        struct vhost_memory_region *reg;
        unsigned int nreg;
        unsigned long offset;
        void *ptr;
        size_t size;

        reg = find_memory_region(mem, addr, &offset, &nreg);
        if (!reg)
            return -EFAULT;

        size = min(len, reg->size - offset);
        ptr = reg->userspace_addr + offset;

        iov[i].iov_base = ptr;
        iov[i].iov_len = size;
        i++;
        ret++;

        addr += size;
        len -= size;
    }

    vhost_dev_unlock_read(dev);

    if (len > 0)
        return -ENOBUFS;

    return ret;
}
